// Verification
package com.jojo.game.verification

import com.jojo.game.*

import java.io.ByteArrayInputStream
import java.nio.charset.StandardCharsets
import java.nio.file.Files
import java.nio.file.Path
import java.util.*
import java.util.zip.GZIPInputStream


/** ConfigFullTraceHarness: Config.js의 전체 게임 인벤토리를 보존한 검증용 압축 데이터이다. */
object ConfigFullTraceHarness {
    /** encoded: 검증 흐름에서 사용하는 값을 담는다. */
    private val encoded = listOf(
        "",
        "",
        "",
        ""
    ).joinToString("")

    /** inventory: 검증 흐름에 필요한 동작을 실행하고 결과를 반환한다. */
    private fun inventory(): String = String(
        GZIPInputStream(ByteArrayInputStream(Base64.getDecoder().decode(encoded))).readBytes(),
        StandardCharsets.UTF_8
    )

    /** main: 검증 실행 흐름을 시작하고 종료 상태를 반환한다. */
    @JvmStatic
    fun main(args: Array<String>) {
        val output = "{\"all_enumerable_config_exports\":${inventory()}}"
        val path = Path.of(args[1])
        Files.createDirectories(path.parent)
        Files.writeString(path, output)
    }
}
